1	import { policyBasePremium, policyInsuranceSum } from "./price-list.js";
2	import { type Item } from "./item.js";
3	import { itemRiskSurcharges } from "./item-risk.js";
4	import { policyModifiers } from "./customer-standing.js";
5	import { type Customer } from "./customer.js";
6	import { roundPayoutInMHPCOFavour, roundPremiumInMHPCOFavour } from "./mhpco-rounding.js";
7	import { capPayout, incidentReimbursement, payoutCap, type Incident } from "./claims.js";
8	import { coverageOf } from "./policy-coverage.js";
9	
10	export type { Item, Customer };
11	export type { Incident, Damage } from "./claims.js";
12	
13	/** A policy MHPCO has written: what it covers and what it was quoted for. */
14	export interface Policy {
15	  readonly premium: number;
16	  readonly insuranceSum: number;
17	  readonly items: readonly Item[];
18	  /** What the office may still pay out on this policy. */
19	  readonly remainingCap: number;
20	}
21	
22	/**
23	 * The settlement of one claim: what MHPCO pays, and the policy as it stands
24	 * afterwards — a claim consumes part of the cap, so later claims against the
25	 * same policy are settled against what is left.
26	 */
27	export interface Settlement {
28	  readonly payout: number;
29	  /**
30	   * What the office may still pay out, reported alongside the payout because
31	   * the claim result states it. The policy carried forward is the one record of
32	   * that fact; this field only repeats it for the caller's convenience.
33	   */
34	  readonly remainingCap: number;
35	  readonly policy: Policy;
36	}
37	
38	/**
39	 * Writes a policy for the items the customer wishes to insure: the premium they
40	 * owe, and the insurance sum the office's payouts are measured against.
41	 */
42	export function createPolicy(customer: Customer, items: readonly Item[]): Policy {
43	  const insuranceSum = policyInsuranceSum(items);
44	  return {
45	    premium: quote(customer, items),
46	    insuranceSum,
47	    items,
48	    remainingCap: payoutCap(insuranceSum),
49	  };
50	}
51	
52	/** Settles a damage report against a policy MHPCO has written. */
53	export function claim(policy: Policy, incident: Incident): Settlement {
54	  const owed = incidentReimbursement(incident, coverageOf(policy.items));
55	  const { payout, remainingCap } = capPayout(roundPayoutInMHPCOFavour(owed), policy.remainingCap);
56	  const settledPolicy: Policy = { ...policy, remainingCap };
57	  return { payout, remainingCap: settledPolicy.remainingCap, policy: settledPolicy };
58	}
59	
60	/** MHPCO adds a flat processing fee to every premium, at the very end. */
61	const PROCESSING_FEE_G = 5;
62	
63	/**
64	 * Assembles the bill in the order the office bills it: the price-list base
65	 * premium of the policy, the risk surcharges its individual items carry, the
66	 * modifiers rated on the policy as a whole, and finally the processing fee.
67	 *
68	 * Each of those amounts is ruled on elsewhere; this function only knows the
69	 * order they are applied in and that the total is rounded once, at the end.
70	 */
71	export function quote(customer: Customer, items: readonly Item[]): number {
72	  const policyBase = policyBasePremium(items);
73	  const premium =
74	    policyBase +
75	    itemRiskSurcharges(items) +
76	    policyModifiers(customer, policyBase) +
77	    PROCESSING_FEE_G;
78	  return roundPremiumInMHPCOFavour(premium);
79	}
