/** Settles a damage report against a policy MHPCO has written. */
export function claim(policy: Policy, incident: Incident): Settlement {
  const owed = incidentReimbursement(incident, coverageOf(policy.items));
  const { payout, remainingCap } = capPayout(roundPayoutInMHPCOFavour(owed), policy.remainingCap);
  const settledPolicy: Policy = { ...policy, remainingCap };
  return { payout, remainingCap: settledPolicy.remainingCap, policy: settledPolicy };
}

